 state.page=Math.max(0,Math.min(state.page,totalPages-1));
 $('detailRows').innerHTML=x.slice(state.page*pp,(state.page+1)*pp).map(r=>`<tr class="${r.esDevolucion?'fila-devolucion':''}"><td>${safe(r.guia)}</td><td>${safe(r.pdv)}</td><td>${safe(r.department)}</td><td>${safe(r.province)}</td><td>${safe(r.district)}</td><td>${safe(r.descarga)}</td><td>${safe(r.firma)}</td><td>${num(r.horas,2)}</td><td>${r.esDevolucion?'No aplica':safe(C.LABELS[r.band])}</td><td>${r.esDevolucion?'–':r.pago+'%'}</td><td class="devolucion-num">${r.esDevolucion?'1':'–'}</td><td>${safe(r.devolver||'')}</td><td>${safe(r.origenPct)}</td><td>${safe(r.fuente)}</td></tr>`).join('')||'<tr><td colspan="14" class="empty">No hay guías para esta selección.</td></tr>';
 $('pageInfo').textContent=`${state.page+1}/${totalPages}`;
